![medium](https://www.gstatic.com/codereviewagent/medium-priority.svg)

To ensure robustness and prevent silent failures, all CUDA API calls (`cudaGetDevice` and `cudaMemcpyAsync`) should be wrapped in `TLLM_CUDA_CHECK`. Additionally, calculating the byte size using `((mOutputDtype.bits + 7) / 8)` instead of `(mOutputDtype.bits / 8)` is safer as it prevents truncation or division-by-zero for potential sub-byte data types.

```
    if (!do_finalize) {
      int64_t expanded_num_rows = num_rows * experts_per_token;
      int device_id;
      TLLM_CUDA_CHECK(cudaGetDevice(&device_id));

      void* fc2_result_ptr = mKernelRunner->getGemm2ResultPtr();
      size_t gemm2_bytes = expanded_num_rows * hidden_size * ((mOutputDtype.bits + 7) / 8);
      auto gemm2_output = alloc_tensor({expanded_num_rows, hidden_size}, mOutputDtype,
                                       DLDevice{kDLCUDA, device_id});
      TLLM_CUDA_CHECK(cudaMemcpyAsync(gemm2_output.data_ptr(), fc2_result_ptr, gemm2_bytes,
                                      cudaMemcpyDeviceToDevice, stream));

      auto expanded_idx = alloc_tensor({expanded_num_rows}, dl_int32, DLDevice{kDLCUDA, device_id});
      TLLM_CUDA_CHECK(cudaMemcpyAsync(expanded_idx.data_ptr(), workspace_info.src_to_dest_map,
                                      expanded_num_rows * sizeof(int32_t), cudaMemcpyDeviceToDevice, stream));
```
